import { lazy } from 'react';
import { BarChart3 as IcBarChart3, FileText as IcFileText, LayoutDashboard as IcLayoutDashboard, Settings2 as IcSettings2 } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Insights & Setup — hub page for the Performance menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'PerformanceInsights'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const PerformanceDashboard = lazy(() => import('./PerformanceDashboard'));
const PerformanceReports = lazy(() => import('./PerformanceReports'));
const PerformanceSettings = lazy(() => import('./PerformanceSettings'));

export const TABS = [
  { id: 'dashboard', label: 'Dashboard', icon: IcLayoutDashboard, page: 'PerformanceDashboard', Component: PerformanceDashboard },
  { id: 'reports', label: 'Reports', icon: IcFileText, page: 'PerformanceReports', Component: PerformanceReports },
  { id: 'settings', label: 'Settings', icon: IcSettings2, page: 'PerformanceSettings', Component: PerformanceSettings },
];

export default function PerformanceInsights({ setPage }) {
  return (
    <TabHub
      icon={IcBarChart3}
      eyebrow="Performance"
      title="Insights & Setup"
      subtitle="The performance dashboard, reports and module settings"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
